import * as THREE from 'three';
/** Original school-health room fixtures; no medicine labels, diagnoses or patient records. */
export function buildInfirmaryProps({root,box,sphere,cylinder,label,beam,mat}){
 const group=new THREE.Group();group.name='infirmary.care-fixtures';root.add(group);const named=(o,name)=>(o.name=name,o);
 const rail=named(new THREE.Group(),'infirmary.curtain');group.add(rail);for(const[x,z]of[[-4.75,-2.95],[-4.75,.6],[-2.1,-2.95]])cylinder(.035,.035,2.52,'#94aaa7',x,1.28,z,rail);beam([-4.75,2.54,.6],[-4.75,2.54,-2.95],.045,'#94aaa7',rail);beam([-4.75,2.54,-2.95],[-2.1,2.54,-2.95],.045,'#94aaa7',rail);
 function curtain(x,z,width,yaw){const shape=new THREE.Shape();const n=40;for(let i=0;i<=n;i++){const px=-width/2+i/n*width,pz=Math.sin(i/n*Math.PI*10)*.055;i?shape.lineTo(px,pz):shape.moveTo(px,pz);}for(let i=n;i>=0;i--)shape.lineTo(-width/2+i/n*width,Math.sin(i/n*Math.PI*10)*.055+.024);shape.closePath();const geo=new THREE.ExtrudeGeometry(shape,{depth:2.07,bevelEnabled:false,steps:1});geo.rotateX(-Math.PI/2);const mesh=new THREE.Mesh(geo,mat('#b1cdbf'));mesh.position.set(x,.38,z);mesh.rotation.y=yaw;mesh.castShadow=true;mesh.receiveShadow=true;rail.add(mesh);for(let i=0;i<5;i++){const ring=new THREE.Mesh(new THREE.TorusGeometry(.06,.015,6,12),mat('#dde6d5'));ring.position.set(x+(i-2)*width/5*Math.cos(yaw),2.5,z-(i-2)*width/5*Math.sin(yaw));ring.rotation.y=yaw;rail.add(ring);}}curtain(-3.98,-2.90,1.3,0);curtain(-4.70,-2.10,1.55,Math.PI/2);
 const sink=named(new THREE.Group(),'infirmary.sink');group.add(sink);box(1.48,.91,.83,'#b4c5b7',-.45,.48,-4.30,.08,sink);box(1.64,.12,.99,'#e9eadb',-.45,1.0,-4.30,.07,sink);const profile=[[.025,-.2],[.20,-.20],[.37,-.11],[.47,.035],[.54,.04],[.54,-.025],[.50,-.03],[.40,-.18],[.21,-.265],[.025,-.265]].map(p=>new THREE.Vector2(...p));const basin=new THREE.Mesh(new THREE.LatheGeometry(profile,36),mat('#f7f6e6'));basin.position.set(-.45,1.25,-4.18);basin.scale.z=.76;basin.castShadow=true;sink.add(basin);cylinder(.075,.075,.018,'#8fa4a1',-.45,1.052,-4.18,sink);const pipe=new THREE.CatmullRomCurve3([new THREE.Vector3(-.45,1.05,-4.64),new THREE.Vector3(-.45,1.52,-4.64),new THREE.Vector3(-.45,1.59,-4.44),new THREE.Vector3(-.45,1.47,-4.30)]);sink.add(new THREE.Mesh(new THREE.TubeGeometry(pipe,24,.036,8,false),mat('#91a7aa')));box(.16,.28,.13,'#c6dfc9',.17,1.20,-4.52,.035,sink);box(.22,.045,.08,'#6d938b',.17,1.365,-4.51,.02,sink);box(.40,.42,.18,'#e6dfc9',.83,1.93,-4.73,.045,sink);box(.30,.30,.02,'#fff8e7',.83,1.66,-4.62,.008,sink);label('비누로 30초 이상',-.50,2.70,-4.71,1.8,'#365c51','#f4ecd4');
 const supplies=named(new THREE.Group(),'infirmary.supply-display');group.add(supplies);for(const[x,z]of[[2.7,-3.8],[3.2,-3.7],[3.7,-3.85]]){box(.32,.31,.25,'#faf4e2',x,1.57,z,.025,supplies);box(.23,.055,.025,'#a2c7bc',x,1.58,z+.14,.01,supplies);}for(const x of[4.1,4.43]){const roll=cylinder(.12,.12,.23,'#eee8d5',x,1.54,-3.60,supplies);roll.rotation.x=Math.PI/2;cylinder(.045,.045,.008,'#aaa995',x,1.54,-3.477,supplies).rotation.x=Math.PI/2;}
 const therm=named(new THREE.Group(),'infirmary.thermometer');group.add(therm);box(.66,.06,.29,'#aac4bd',3.40,1.46,-3.20,.04,therm);box(.47,.055,.10,'#f5f5e5',3.40,1.52,-3.20,.035,therm);box(.15,.065,.11,'#719f99',3.16,1.52,-3.20,.025,therm);box(.09,.009,.055,'#839c9b',3.4,1.553,-3.20,.008,therm);label('구급 물품',3.5,.90,-3.145,1.30,'#365c51','#f4ecd4');
 const desk=named(new THREE.Group(),'infirmary.consultation');group.add(desk);box(1.9,.14,1.04,'#d3b891',2.65,1.0,.55,.07,desk);for(const x of[1.88,3.42])for(const z of[.18,.92])box(.12,.91,.12,'#94ada1',x,.48,z,.02,desk);box(.72,.06,.51,'#7da69a',2.35,1.105,.5,.025,desk);box(.62,.022,.41,'#f6f0da',2.35,1.15,.50,.01,desk);cylinder(.10,.09,.23,'#91aeb1',3.20,1.18,.38,desk);box(.88,.12,.75,'#a1baaa',2.65,.52,-1.02,.07,desk);box(.88,.56,.14,'#91afa0',2.65,.88,-1.35,.07,desk);for(const x of[2.34,2.96])for(const z of[-1.28,-.75])box(.08,.44,.08,'#9c9a82',x,.26,z,.015,desk);
 return group;
}
